#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Roda a partir da RAIZ do repo (o deploy usa 'gcloud run deploy --source .', que
# precisa enxergar o Dockerfile). O script vive em scripts/, entao sobe um nivel.
REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$REPO_ROOT"
SERVICO="agentepi"

banner "Deploy do Agente PI no Google Cloud Run (sai do Render)"

# ── Stage 1: gcloud instalado ─────────────────────────────────────────────
stage "Pre-requisito — gcloud CLI"
say "O deploy usa a CLI do Google Cloud. Se ja tem 'gcloud', pule a instalacao."
if ! command -v gcloud >/dev/null 2>&1; then
  warn "gcloud NAO encontrado no PATH."
  open_url "https://cloud.google.com/sdk/docs/install"
  say "Instale o Google Cloud SDK, ABRA UM NOVO terminal e rode este script de novo."
  say "Alternativa sem instalar nada: abra o Cloud Shell (console.cloud.google.com,"
  say "icone >_ no topo), faca 'git clone' do repo la e rode este script dentro dele."
  exit 1
fi
note "gcloud encontrado: $(command -v gcloud)"
pause "Pronto para logar no Google Cloud?"

# ── Stage 2: login + projeto + APIs ───────────────────────────────────────
stage "Login, projeto e APIs"
say "Abrindo o login do Google Cloud no navegador..."
gcloud auth login
say "Use o MESMO projeto onde o BigQuery/landscape ja roda (assim o landscape usa a"
say "service account de runtime, sem precisar de JSON)."
ask GCP_PROJECT "ID do projeto GCP (ex.: meu-projeto-123):"
gcloud config set project "$GCP_PROJECT"
say "Habilitando as APIs necessarias (Cloud Run + Cloud Build)..."
gcloud services enable run.googleapis.com cloudbuild.googleapis.com

# ── Stage 3: credenciais do servidor ──────────────────────────────────────
stage "Credenciais do servidor (as que voce ja tem guardadas)"
say "Vao virar variaveis de ambiente do servico no Cloud Run. A entrada e OCULTA."
ask_secret API_KEY_AGENTE_PI "API_KEY_AGENTE_PI (a chave que o Copilot usa no header X-API-Key):"
ask_secret MOTHERDUCK_TOKEN  "MOTHERDUCK_TOKEN (acesso ao banco no MotherDuck):"
ask        EPO_OPS_KEY       "EPO_OPS_KEY (consumer key do EPO OPS):"
ask_secret EPO_OPS_SECRET    "EPO_OPS_SECRET (consumer secret do EPO OPS):"
note "Guardando uma copia local em .env (gitignorado) para re-runs."
write_env API_KEY_AGENTE_PI "$API_KEY_AGENTE_PI"
write_env MOTHERDUCK_TOKEN  "$MOTHERDUCK_TOKEN"
write_env EPO_OPS_KEY       "$EPO_OPS_KEY"
write_env EPO_OPS_SECRET    "$EPO_OPS_SECRET"

# ── Stage 4: deploy ───────────────────────────────────────────────────────
stage "Deploy no Cloud Run"
ask REGION "Regiao (Enter = southamerica-east1 / Sao Paulo):"
[[ -z "$REGION" ]] && REGION="southamerica-east1"
say "Vou rodar 'gcloud run deploy' a partir do codigo deste repo. O Cloud Build"
say "constroi a imagem (Dockerfile) e publica o servico '$SERVICO' na regiao $REGION."
warn "Isso cria/atualiza um servico publico (protegido pela SUA chave X-API-Key)."
if confirm "Fazer o deploy agora?"; then
  # '^@^' troca o delimitador de virgula para '@' -- assim tokens com virgula nao quebram.
  gcloud run deploy "$SERVICO" \
    --source . \
    --region "$REGION" \
    --allow-unauthenticated \
    --set-env-vars "^@^API_KEY_AGENTE_PI=${API_KEY_AGENTE_PI}@MOTHERDUCK_TOKEN=${MOTHERDUCK_TOKEN}@EPO_OPS_KEY=${EPO_OPS_KEY}@EPO_OPS_SECRET=${EPO_OPS_SECRET}"
else
  warn "Deploy cancelado. Rode o script de novo quando quiser (nada foi publicado)."
  exit 1
fi

# ── Stage 5: BigQuery/landscape (opcional) ────────────────────────────────
stage "Permissao do BigQuery (so se usar o landscape no Copilot)"
say "O landscape consulta o BigQuery. Para funcionar, a service account de runtime do"
say "servico precisa de permissao de BigQuery. Se voce NAO usa landscape, pode pular."
if confirm "Conceder BigQuery Job User a service account do servico?"; then
  SA="$(gcloud run services describe "$SERVICO" --region "$REGION" \
        --format='value(spec.template.spec.serviceAccountName)')"
  [[ -z "$SA" ]] && SA="$(gcloud iam service-accounts list \
        --filter='displayName:Default compute' --format='value(email)' | head -n1)"
  say "Service account: $SA"
  if gcloud projects add-iam-policy-binding "$GCP_PROJECT" \
        --member="serviceAccount:${SA}" --role="roles/bigquery.jobUser" >/dev/null 2>&1 \
     && gcloud projects add-iam-policy-binding "$GCP_PROJECT" \
        --member="serviceAccount:${SA}" --role="roles/bigquery.dataViewer" >/dev/null 2>&1; then
    note "Permissoes concedidas (jobUser + dataViewer)."
  else
    SKIPPED+=("BigQuery: nao consegui conceder o papel (permissao?). Rode manualmente com a conta owner do projeto -- ver docs/deploy-cloudrun.md")
    warn "Nao consegui conceder o papel automaticamente (talvez sua conta nao seja admin do projeto)."
  fi
else
  SKIPPED+=("BigQuery: landscape nao vai funcionar ate conceder o papel a service account")
  note "Pulado. Landscape fica indisponivel ate voce conceder a permissao."
fi

# ── Stage 6: verificar ────────────────────────────────────────────────────
stage "Verificar o servico no ar"
URL="$(gcloud run services describe "$SERVICO" --region "$REGION" --format='value(status.url)')"
say "URL do servico: ${URL}"
say "Endpoint MCP para o Copilot: ${URL}/mcp"
say "Conferindo a lista de tools (sem auth)..."
if command -v curl >/dev/null 2>&1; then
  TOTAL="$(curl -s "${URL}/tools" 2>/dev/null | grep -o '"total":[0-9]*' | head -n1 || true)"
  note "resposta de /tools: ${TOTAL:-<sem resposta - o cold start pode levar ~2s, tente abrir no navegador>}"
fi
open_url "${URL}/tools"
write_env AGENTEPI_URL "$URL"
SKIPPED+=("Copilot Studio: troque a Server URL da conexao MCP para ${URL}/mcp (mesma X-API-Key) e ligue 'Allow all'")
SKIPPED+=("Render: DELETE (ou suspenda) o servico AgentePI e desligue o keep-alive (cron-job.org/UptimeRobot)")
SKIPPED+=("Teste no Copilot: 'Quanto a Clarke pagou de anuidades em marco/2025 vs 2026?' -> R\$ 822.836 / R\$ 1.344.700")

finish
